package com.ahdre.pip;
import android.content.*;import android.util.Base64;import org.json.*;import java.util.*;import java.net.*;import java.io.*;import java.security.*;import java.security.spec.*;import java.security.interfaces.*;import javax.crypto.*;import javax.crypto.spec.*;import java.math.BigInteger;

class FriendsRelay {
 final SharedPreferences prefs;JSONObject saved;PrivateKey privateKey;byte[] modulus;JSONObject visit;String peer="",name="Пип";int accessory;double lastReceived,lastBeat;
 static final String HOST="https://ntfy.sh/";static final SecureRandom random=new SecureRandom();
 static byte[] hash(byte[] b)throws Exception{return MessageDigest.getInstance("SHA-256").digest(b);}
 static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format(Locale.ROOT,"%02x",v&255));return s.toString();}
 static String b64(byte[] b){return Base64.encodeToString(b,Base64.NO_WRAP);}
 static byte[] un64(String s){return Base64.decode(s,Base64.DEFAULT);}
 static byte[] secret(String code)throws Exception{String[] a=code.split("\\.");if(a.length!=3||!a[0].equals("PIP1")||a[1].length()!=43||a[2].length()!=16)throw new IOException("Код друга не подходит");byte[] b=Base64.decode(a[1],Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING);if(b.length!=32)throw new IOException("Код друга не подходит");return b;}
 static String topic(String code)throws Exception{secret(code);return "pip-v1-"+hex(hash(code.getBytes("UTF-8"))).substring(0,40);}
 static byte[] key(String code,String purpose)throws Exception{return hash((b64(secret(code))+purpose).getBytes("UTF-8"));}
 static byte[] mac(byte[] key,byte[] bytes)throws Exception{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(key,"HmacSHA256"));return m.doFinal(bytes);}
 static String seal(String code,String plain)throws Exception{byte[] iv=new byte[16];random.nextBytes(iv);Cipher c=Cipher.getInstance("AES/CBC/PKCS5Padding");c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(key(code,"enc"),"AES"),new IvParameterSpec(iv));byte[] encrypted=c.doFinal(plain.getBytes("UTF-8"));byte[] data=new byte[16+encrypted.length];System.arraycopy(iv,0,data,0,16);System.arraycopy(encrypted,0,data,16,encrypted.length);return b64(data)+"."+b64(mac(key(code,"mac"),data));}
 static String open(String code,String text)throws Exception{if(text.length()>6000)throw new IOException();String[] a=text.split("\\.");if(a.length!=2)throw new IOException();byte[] data=un64(a[0]),tag=un64(a[1]);if(data.length<32||!MessageDigest.isEqual(tag,mac(key(code,"mac"),data)))throw new IOException();Cipher c=Cipher.getInstance("AES/CBC/PKCS5Padding");c.init(Cipher.DECRYPT_MODE,new SecretKeySpec(key(code,"enc"),"AES"),new IvParameterSpec(Arrays.copyOfRange(data,0,16)));return new String(c.doFinal(data,16,data.length-16),"UTF-8");}
 FriendsRelay(SharedPreferences p)throws Exception{prefs=p;String stored=p.getString("relay","");if(stored.isEmpty()){KeyPairGenerator gen=KeyPairGenerator.getInstance("RSA");gen.initialize(2048);KeyPair kp=gen.generateKeyPair();privateKey=kp.getPrivate();byte[] raw=((RSAPublicKey)kp.getPublic()).getModulus().toByteArray();modulus=raw.length==257?Arrays.copyOfRange(raw,1,raw.length):raw;byte[] sec=new byte[32];random.nextBytes(sec);String code="PIP1."+Base64.encodeToString(sec,Base64.URL_SAFE|Base64.NO_PADDING|Base64.NO_WRAP)+"."+hex(hash(modulus)).substring(0,16);saved=new JSONObject().put("code",code).put("privateKey",b64(privateKey.getEncoded())).put("n",b64(modulus)).put("friends",new JSONArray()).put("seen",new JSONArray()).put("budgetDay","").put("sent",0);save();}else{saved=new JSONObject(stored);privateKey=KeyFactory.getInstance("RSA").generatePrivate(new PKCS8EncodedKeySpec(un64(saved.getString("privateKey"))));modulus=un64(saved.getString("n"));}prefs.edit().putString("socialCode",code()).apply();}
 String code(){return saved.optString("code");}void save(){prefs.edit().putString("relay",saved.toString()).apply();}
 double now(){return System.currentTimeMillis()/1000.0;}
 JSONObject find(String code)throws Exception{JSONArray f=saved.getJSONArray("friends");for(int i=0;i<f.length();i++)if(f.getJSONObject(i).getString("code").equals(code))return f.getJSONObject(i);return null;}
 void remove(String code)throws Exception{JSONArray f=saved.getJSONArray("friends");for(int i=f.length()-1;i>=0;i--)if(f.getJSONObject(i).getString("code").equals(code))f.remove(i);}
 void expire(double now){if(visit!=null&&(now>=visit.optDouble("expires")||(!visit.optString("status").equals("pending")&&now-lastReceived>45)))visit=null;}
 JSONObject pet(JSONObject f,double now)throws Exception{return new JSONObject().put("id",f.getString("code")).put("code",f.getString("code")).put("name",f.optString("name","Пип")).put("accepted",f.optBoolean("accepted")).put("incoming",f.optBoolean("incoming")).put("online",now-f.optDouble("seen")<60);}
 JSONObject snapshot(double now)throws Exception{expire(now);JSONArray friends=new JSONArray(),arr=saved.getJSONArray("friends");for(int i=0;i<arr.length();i++)friends.put(pet(arr.getJSONObject(i),now));return new JSONObject().put("code",code()).put("friends",friends).put("visits",visit==null?new JSONArray():new JSONArray().put(visit));}
 synchronized JSONObject perform(String route,JSONObject p,String localName,int acc)throws Exception{name=localName;accessory=acc;double now=now();expire(now);poll(now);String other=p.optString("friend");JSONObject f=find(other);
  if(route.equals("/friend/request")){other=p.getString("code").trim();secret(other);if(other.equals(code()))throw new IOException("Это твой собственный код");if(find(other)!=null)throw new IOException("Друг уже в списке");if(saved.getJSONArray("friends").length()>=30)throw new IOException("В списке уже 30 друзей");send(other,"friend_request",null,now+86400);saved.getJSONArray("friends").put(new JSONObject().put("code",other).put("name","Ожидаем друга").put("accepted",false).put("incoming",false));}
  else if(route.equals("/friend/accept")){if(f==null||!f.optBoolean("incoming")||f.optBoolean("accepted"))throw new IOException("Нет входящего запроса");send(other,"friend_accept",null,now+86400);f.put("accepted",true);}
  else if(route.equals("/friend/remove")){if(f!=null){send(other,"friend_remove",null,now+60);remove(other);if(peer.equals(other))visit=null;}}
  else if(route.equals("/visit/request")){if(f==null||!f.optBoolean("accepted"))throw new IOException("Сначала подтвердите дружбу");if(visit!=null)throw new IOException("Визит уже существует");String id=UUID.randomUUID().toString().replace("-","");send(other,"offer",id,now+120);peer=other;visit=new JSONObject().put("id",id).put("status","pending").put("outgoing",true).put("expires",now+120).put("pet",pet(f,now));}
  else if(route.equals("/visit/accept")){if(visit==null||visit.optBoolean("outgoing")||!visit.optString("status").equals("pending"))throw new IOException("Нет входящего визита");send(peer,"accept",visit.getString("id"),now+180);visit.put("status","ready").put("expires",now+180);lastReceived=now;}
  else if(route.equals("/visit/end")||route.equals("/disconnect")){if(visit!=null)send(peer,"end",visit.getString("id"),now+60);visit=null;}
  if(visit!=null&&visit.optString("status").equals("active")&&now-lastBeat>=20){send(peer,"beat",visit.getString("id"),visit.getDouble("expires"));lastBeat=now;}save();return snapshot(now);
 }
 void send(String dest,String action,String visit,double expiry)throws Exception{String day=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.ROOT){{setTimeZone(TimeZone.getTimeZone("UTC"));}}.format(new Date());if(!saved.optString("budgetDay").equals(day))saved.put("budgetDay",day).put("sent",0);if(saved.optInt("sent")>=190)throw new IOException("Сегодня лимит бесплатной связи исчерпан. Попробуй завтра.");JSONObject m=new JSONObject().put("action",action).put("code",code()).put("name",name).put("accessory",accessory).put("visit",visit==null?JSONObject.NULL:visit).put("nonce",UUID.randomUUID().toString().replace("-","")).put("time",now()).put("expires",expiry);byte[] payload=m.toString().getBytes("UTF-8");Signature sig=Signature.getInstance("SHA256withRSA");sig.initSign(privateKey);sig.update(payload);JSONObject envelope=new JSONObject().put("payload",b64(payload)).put("sig",b64(sig.sign())).put("n",b64(modulus));request(HOST+topic(dest),seal(dest,envelope.toString()));saved.put("sent",saved.optInt("sent")+1);save();}
 String request(String url,String body)throws Exception{javax.net.ssl.HttpsURLConnection c=(javax.net.ssl.HttpsURLConnection)new URL(url).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(8000);try{if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","text/plain");c.setRequestProperty("Priority","1");try(OutputStream o=c.getOutputStream()){o.write(body.getBytes("UTF-8"));}}if(c.getResponseCode()!=200)throw new IOException("Нет связи или лимит бесплатного сервиса. Пип дома.");try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[2048];int n;while((n=in.read(b))!=-1){if(out.size()+n>262144)throw new IOException();out.write(b,0,n);}return out.toString("UTF-8");}}finally{c.disconnect();}}
 void poll(double now)throws Exception{String response=request(HOST+topic(code())+"/json?poll=1&since=120s",null);for(String line:response.split("\\n")){if(line.trim().isEmpty())continue;try{JSONObject outer=new JSONObject(line);if(!outer.has("message"))continue;JSONObject env=new JSONObject(open(code(),outer.getString("message")));byte[] payload=un64(env.getString("payload")),mod=un64(env.getString("n"));if(mod.length!=256)continue;JSONObject m=new JSONObject(new String(payload,"UTF-8"));String source=m.getString("code");secret(source);if(!source.split("\\.")[2].equals(hex(hash(mod)).substring(0,16))||m.getDouble("time")>now+30||m.getDouble("expires")<now||now-m.getDouble("time")>120||m.getString("name").length()>24||m.getInt("accessory")<0||m.getInt("accessory")>5)continue;String nonce=m.getString("nonce");JSONArray seen=saved.getJSONArray("seen");boolean duplicate=false;for(int i=0;i<seen.length();i++)if(seen.getString(i).equals(nonce))duplicate=true;if(duplicate)continue;PublicKey pub=KeyFactory.getInstance("RSA").generatePublic(new RSAPublicKeySpec(new BigInteger(1,mod),BigInteger.valueOf(65537)));Signature sig=Signature.getInstance("SHA256withRSA");sig.initVerify(pub);sig.update(payload);if(!sig.verify(un64(env.getString("sig"))))continue;JSONObject f=find(source);if(f!=null&&f.has("n")&&!f.getString("n").equals(env.getString("n")))continue;seen.put(nonce);if(seen.length()>512)seen.remove(0);receive(m,env.getString("n"),now);}catch(JSONException e){}catch(GeneralSecurityException e){}catch(IllegalArgumentException e){}catch(IOException e){}}save();}
 void receive(JSONObject m,String n,double now)throws Exception{String source=m.getString("code"),action=m.getString("action");JSONObject f=find(source);if(action.equals("friend_request")){if(f==null&&saved.getJSONArray("friends").length()<30)saved.getJSONArray("friends").put(new JSONObject().put("code",source).put("name",m.getString("name")).put("n",n).put("incoming",true).put("accepted",false).put("seen",now));else if(f!=null&&!f.optBoolean("accepted"))f.put("n",n).put("name",m.getString("name")).put("incoming",true);return;}if(f==null)return;if(action.equals("friend_accept")){f.put("n",n).put("name",m.getString("name")).put("accepted",true).put("seen",now);return;}if(action.equals("friend_remove")){remove(source);if(peer.equals(source))visit=null;return;}if(!f.optBoolean("accepted"))return;f.put("name",m.getString("name")).put("seen",now);
  if(action.equals("offer")){if(visit!=null)return;peer=source;visit=new JSONObject().put("id",m.getString("visit")).put("status","pending").put("outgoing",false).put("expires",Math.min(now+120,m.getDouble("expires"))).put("pet",new JSONObject().put("name",m.getString("name")).put("accessory",m.getInt("accessory")).put("id",source));return;}
  if(visit==null||!peer.equals(source)||!visit.getString("id").equals(m.optString("visit")))return;if(action.equals("end")){visit=null;return;}
  if(action.equals("accept")&&visit.optBoolean("outgoing")&&visit.optString("status").equals("pending")){send(peer,"start",visit.getString("id"),m.getDouble("expires"));visit.put("status","active").put("expires",Math.min(now+180,m.getDouble("expires")));lastReceived=lastBeat=now;return;}
  if(action.equals("start")&&!visit.optBoolean("outgoing")&&visit.optString("status").equals("ready")){visit.put("status","active");lastReceived=now;send(peer,"beat",visit.getString("id"),visit.getDouble("expires"));lastBeat=now;return;}if(action.equals("beat")&&visit.optString("status").equals("active"))lastReceived=now;
 }
}
